{
  "criterios": [
    {
      "i": 0,
      "atingido": true,
      "evidencia": "O modelo afirma que 'É seguro viajar, desde que bem preparado' e 'pode usar as casas de oxigênio comuns a uma altura moderada', liberando a viagem com ressalvas."
    },
    {
      "i": 1,
      "atingido": false,
